public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build the adjacency list representation of the tree
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Helper method to find the minimum time to collect all apples starting from a node
    return dfs(0, -1, hasApple, graph);
}

private int dfs(int node, int parent, boolean[] hasApple, List<List<Integer>> graph) {
    int time = 0;
    // Iterate through the neighbors of the current node
    for (int child : graph.get(node)) {
        if (child == parent) {
            continue;
        }

        // Recursively find the time to collect apples from the child node
        int appleTime = dfs(child, node, hasApple, graph);

        // If the child node has an apple or there's an apple on the path from parent to the child
        if (appleTime > 0 || hasApple[child]) {
            // Add 2 to the time for the flat path and 2 additional time for the u-turn (if different from parent)
            time += appleTime + (child != parent);
        }
    }
    return time;
}

