public int findMinFibonacciNumbers(int k) {
        int[] fibSequence = {0, 1};
        int fibIndex = 0;
        int sequenceSum = 0;

        // Generate Fibonacci sequence up to a point where the next number is equal to or greater than k
        while (true) {
            int nextFib = fibSequence[fibIndex] + fibSequence[fibIndex + 1];
            if (nextFib >= k) {
                break;
            } else {
                fibSequence[fibIndex + 1] = nextFib;
                fibIndex++;
            }
        }

        int count = 0;
        for (int i = fibSequence.length - 1; i >= 0; i--) {
            while (sequenceSum + fibSequence[i] <= k) {
                count++;
                sequenceSum += fibSequence[i];
            }
        }

        return count;
    }

