    for (int k = -Math.min(rowLength, colLength); k <= Math.max(rowLength, colLength); k++) {
        int curRow = 0;
        int curCol = 0;
        for (int i = 0; i < Math.abs(k); i++) {
            if (k >= 0) {
                curRow++;
                curCol++;
            } else {
                curRow--;
                curCol--;
            }
        }

        while (curRow < rowLength && curCol < colLength) {
            diagonal.add(mat[curRow][curCol]);
            curRow++;
            curCol++;
        }
    }

    return diagonal.stream().mapToInt(i -> i).toArray();
}

public static int findSmallestInteger(int n) {
    if (n == 0) return 0;

    char[] digits = String.valueOf(n).toCharArray();
    int minIndex = -1;

    // Find the first digit that goes to the right of the smallest digit to its left
    for (int i = 0; i < digits.length - 1; i++) {
        if (digits[i] < digits[i + 1]) {
            minIndex = i;
        }
    }

    // If no such digit is found, return -1
    if (minIndex == -1) return -1;

    int lastMinIndex = -1;
    // Find the smallest digit to the right of the smallest digit found
    for (int i = minIndex + 1; i < digits.length; i++) {
        if (digits[i] > digits[minIndex]) {
            lastMinIndex = i;
        }
    }

    // Swap these two digits
    char temp = digits[minIndex];
    digits[minIndex] = digits[lastMinIndex];
    digits[lastMinIndex] = temp;

    // Sort the rest of the digits to get the smallest permutation
    Arrays.sort(digits);

    // Return the integer formed by the rearranged digits
    return Integer.parseInt(new String(digits));
}

public static List<String> centerSymmetricNumbers(int n) {
    ArrayList<String> result = new ArrayList<>();
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    if (n % 2 == 0)
        return centerSymmetricNumbers(n / 2);
    for (int i = 0; i < 10; i++) {
        result.add(String.format("%d%d", i, i));
    }
    for (int i = 1; i <= n / 2 - 1; i++) {
        int temp = 10 * i;
        for (int j = 0; j < 10; j++) {
            char[] arr = new char[2 * i + 1];
            arr[0] = arr[arr.length - 1] = temp + j;
            for (int k = 1, l = 0; k < (2 * i); k++, l++) {
                arr[k] = (char) (j + i + 48);
                if (k % 2 == 0) {
                    arr[2 * i - 1 - k] = arr[k + 1];
                }
                l--;
            }
            result.add(new String(arr));
        }
    }
    return result;
}

