public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int count = 1;
    List<Integer> uglyNumbers = new ArrayList<>();
    uglyNumbers.add(1);

    int i = 0;
    int j = 0;
    int k = 0;

    while (count < n) {
        int next = Math.min(uglyNumbers.get(i) * 2, Math.min(uglyNumbers.get(j) * 3, uglyNumbers.get(k) * 5));
        uglyNumbers.add(next);
        if (next == uglyNumbers.get(i) * 2) i++;
        if (next == uglyNumbers.get(j) * 3) j++;
        if (next == uglyNumbers.get(k) * 5) k++;
        count++;
    }

    return uglyNumbers.get(n - 1);
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxLength = 1;
    int count = 1;
    char prevChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == prevChar) {
            count++;
            maxLength = Math.max(maxLength, count);
        } else {
            count = 1;
            prevChar = s.charAt(i);
        }
    }

    return maxLength;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> list = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        list.add(i);
    }
    Collections.sort(list);
    return list;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    for (int num : nums) {
        uniqueElements.add(num);
    }
    return uniqueElements.stream().mapToInt(Integer::intValue).sum();
}

public static int minPerfectSquareSum(int n) {
    if (n < 1) {
        return 0;
    }

    int[] dp = new int[n + 1];
    dp[1] = 1;

    for (int i = 2; i <= n; i++) {
        int minSum = Integer.MAX_VALUE;
        for (int j = 1; j <=Math.sqrt(i); j++) {
            minSum = Math.min(minSum, 1 + dp[i - j * j]);
        }
        dp[i] = minSum;
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    StringBuilder result = new StringBuilder();
    StringBuilder currentWord = new StringBuilder();

    for (char c : s.toCharArray()) {
        if (c == ' ') {
            // Reverse the current word and append it to the result
            result.append(currentWord.reverse()).append(" ");
            currentWord.setLength(0); // Reset current word for the next word
        } else {
            currentWord.append(c);
        }
    }

    // Append the last word after the last space
    result.append(currentWord.reverse());

    return result.toString();
}
